1	// Package govflow implements proposal lifecycle and treasury execution.
2	package govflow
3	
4	import "sort"
5	
6	// Proposal is one governance proposal with its voting window.
7	type Proposal struct {
8		ID           string
9		Title        string
10		State        string
11		ForVotes     int64
12		AgainstVotes int64
13		Quorum       int64
14		TimelockEnd  int64
15		Actions      []string
16	}
17	
18	// Vote records a weighted vote against an open proposal.
19	// 只增加所选一侧的累计权重；累加结果在 [0, math.MaxInt64] 内才接受，
20	// 恰好达到上限也算成功。超过上限返回说明权重溢出的错误，且不改写任何一侧：
21	// 不截断、不变负、不挪到另一侧，后续仍能容纳的投票不受影响。
22	func Vote(proposal *Proposal, weight int64, support bool) error {
23		if proposal.State != "voting" {
24			return errInvalid("proposal is not open for voting")
25		}
26		if weight <= 0 {
27			return errInvalid("vote weight must be positive")
28		}
29		if support {
30			sum, ok := addInt64(proposal.ForVotes, weight)
31			if !ok {
32				return errInvalid("vote weight overflow: for-side total would exceed 9223372036854775807")
33			}
34			proposal.ForVotes = sum
35		} else {
36			sum, ok := addInt64(proposal.AgainstVotes, weight)
37			if !ok {
38				return errInvalid("vote weight overflow: against-side total would exceed 9223372036854775807")
39			}
40			proposal.AgainstVotes = sum
41		}
42		return nil
43	}
44	
45	// Tally returns the state a proposal moves to under quorum and majority rules.
46	// 只返回结论，不改写提案状态、票数或任何执行动作。
47	// 法定人数与严格多数的判定复用投票提案唯一的通过规则 votePasses，
48	// 保证两侧合计溢出 int64（乃至恰好为上限）时结论仍正确。
49	func Tally(proposal *Proposal) string {
50		if proposal.State != "voting" {
51			return proposal.State
52		}
53		if votePasses(proposal.ForVotes, proposal.AgainstVotes, proposal.Quorum) {
54			return "passed"
55		}
56		return "rejected"
57	}
58	
59	// Executable lists passed proposals whose timelock elapsed, stable by id.
60	func Executable(proposals []Proposal, now int64) []string {
61		var ready []string
62		for _, proposal := range proposals {
63			if proposal.State == "passed" && now >= proposal.TimelockEnd && len(proposal.Actions) > 0 {
64				ready = append(ready, proposal.ID)
65			}
66		}
67		sort.Strings(ready)
68		return ready
69	}
70	
71	type errInvalid string
72	
73	func (e errInvalid) Error() string { return string(e) }
