1	package govflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"io/fs"
10		"os"
11		"path/filepath"
12		"reflect"
13		"sort"
14		"strconv"
15		"strings"
16		"sync"
17		"syscall"
18	)
19	
20	// 资金库状态文件相关错误。
21	var (
22		// ErrTreasuryAlreadyInit：初始化目标路径已存在文件，新文件才能初始化。
23		ErrTreasuryAlreadyInit = errors.New("treasury init refused: state file already exists")
24		// ErrStateCorrupt：状态文件损坏或不是受支持的资金库状态文件。
25		ErrStateCorrupt = errors.New("treasury state file is corrupt")
26		// ErrProposalNotFound：按编号查询或执行时提案不存在。
27		ErrProposalNotFound = errors.New("proposal not found")
28		// ErrProposalConflict：同编号提案再次登记但时间锁或动作原文与首次不同。
29		ErrProposalConflict = errors.New("proposal already registered with different timelock or actions")
30		// ErrInvalidRegistration：登记参数非法（编号为空、初始余额越界等）。
31		ErrInvalidRegistration = errors.New("invalid registration")
32	)
33	
34	const (
35		stateMagic   = "govflow-treasury-state"
36		stateVersion = 1
37		lockSuffix   = ".lock"
38	)
39	
40	// BalanceUpdate 记录一个账户在一次动作前后的余额。
41	//
42	// before 与 after 必须各自明确写出且为 int64 整数：字段缺失、为 null 或
43	// 类型不符都不得被折叠成 0 再当作合法凭据读出——某个余额本来应为 0 时，
44	// 缺失字段与明确写出的 0 在解码后必须仍可区分。因此解码时保留字段的原始
45	// JSON，由 validateReceiptActionBalances 区分“缺失/空值/类型不符”。
46	type BalanceUpdate struct {
47		Account string `json:"account"`
48		Before  int64  `json:"before"`
49		After   int64  `json:"after"`
50	
51		beforeRaw json.RawMessage
52		afterRaw  json.RawMessage
53	}
54	
55	// balanceUpdateJSONShape 只用于解码，按保存格式的字段名逐字接住每个字段的原始 JSON。
56	type balanceUpdateJSONShape struct {
57		Account string          `json:"account"`
58		Before  json.RawMessage `json:"before"`
59		After   json.RawMessage `json:"after"`
60	}
61	
62	// UnmarshalJSON 保留 before/after 是否出现及其原始写法（缺失为 nil、null 为
63	// "null"），使“字段缺失”与“显式写出 0”在解码后仍可区分：encoding/json 直接
64	// 解进 int64 会把缺失/null/类型不符都折叠成 0。判定统一交给
65	// validateReceiptActionBalances，此处只在字段确实是 int64 整数时填充值。
66	func (u *BalanceUpdate) UnmarshalJSON(data []byte) error {
67		var shape balanceUpdateJSONShape
68		if err := json.Unmarshal(data, &shape); err != nil {
69			return err
70		}
71		u.Account = shape.Account
72		u.beforeRaw, u.afterRaw = shape.Before, shape.After
73		fillInt64(shape.Before, &u.Before)
74		fillInt64(shape.After, &u.After)
75		return nil
76	}
77	
78	// mustBalanceUpdate 构造一份内存中的合法余额记录（首次执行构造凭据使用）。
79	// 同步填上字段原始片段，使“提交前校验”与“打开重放校验”走同一份
80	// validateReceiptActionBalances 判定时不会把本进程新建的凭据误判为字段缺失。
81	func mustBalanceUpdate(account string, before, after int64) BalanceUpdate {
82		beforeRaw, _ := json.Marshal(before)
83		afterRaw, _ := json.Marshal(after)
84		return BalanceUpdate{
85			Account: account, Before: before, After: after,
86			beforeRaw: beforeRaw, afterRaw: afterRaw,
87		}
88	}
89	
90	// ActionReceipt 是凭据中对单项动作的留痕：动作原文、在提案中的顺序编号（0 起），
91	// 以及该动作引发的资金库与收款账户余额变动。两侧的 before/after 四个余额字段
92	// 都必须明确写出；任何一个缺失、为 null 或类型不符，整份状态文件即判损坏，
93	// 不能根据转账金额、账户余额或其它凭据补出（见 validateReceiptActionBalances）。
94	//
95	// index 同样必须明确写出：它是执行留痕的一部分，记录恰好排在 actions 第一项
96	// 并不能补出一个合法的 0。字段缺失、为 null、不是 int64 范围内的非负整数
97	// （字符串/布尔/小数/指数/超界/负数）或与该动作在凭据中的实际位置不符，都判
98	// 整份状态损坏（见 validateReceiptActionIndex）。因此解码时保留 index 的原始
99	// JSON，与余额字段走同一套“缺失/空值/类型不符”判定。
100	type ActionReceipt struct {
101		Index     int64         `json:"index"`
102		Action    string        `json:"action"`
103		Treasury  BalanceUpdate `json:"treasury"`
104		Recipient BalanceUpdate `json:"recipient"`
105	
106		indexRaw json.RawMessage
107	}
108	
109	// actionReceiptJSONShape 只用于解码，按保存格式的字段名逐字接住每个字段的原始 JSON。
110	type actionReceiptJSONShape struct {
111		Index     json.RawMessage `json:"index"`
112		Action    string          `json:"action"`
113		Treasury  BalanceUpdate   `json:"treasury"`
114		Recipient BalanceUpdate   `json:"recipient"`
115	}
116	
117	// UnmarshalJSON 保留 index 是否出现及其原始写法（缺失为 nil、null 为 "null"），
118	// 使“字段缺失”与“显式写出 0”在解码后仍可区分：encoding/json 直接解进 int64
119	// 会把缺失/null/类型不符都折叠成 0，第一项动作缺失 index 时就会被误当成合法
120	// 编号 0。判定统一交给 validateReceiptActionIndex，此处只在字段确实是 int64
121	// 整数时填充值。
122	func (a *ActionReceipt) UnmarshalJSON(data []byte) error {
123		var shape actionReceiptJSONShape
124		if err := json.Unmarshal(data, &shape); err != nil {
125			return err
126		}
127		a.Action = shape.Action
128		a.Treasury = shape.Treasury
129		a.Recipient = shape.Recipient
130		a.indexRaw = shape.Index
131		fillInt64(shape.Index, &a.Index)
132		return nil
133	}
134	
135	// Receipt 是一项提案首次成功执行后生成的执行凭据。
136	// 一项提案只允许成功一次；重试返回同一份凭据。
137	//
138	// executed_at 必须明确写出且不得早于对应提案的 timelock_end：首次执行只在
139	// now 达到时间锁后发生，保存的凭据必须满足同一条执行资格规则。字段缺失、
140	// 为 null 或类型不符都不得被折叠成 0 再当作合法凭据读出，因此解码时保留
141	// 字段的原始 JSON，由 validateState 区分“缺失/空值/类型不符/早于时间锁”。
142	type Receipt struct {
143		ProposalID string          `json:"proposal_id"`
144		ExecutedAt int64           `json:"executed_at"` // 首次成功执行时调用方提供的时间
145		Order      int64           `json:"order"`       // 成功提交的先后顺序，0 起
146		Actions    []ActionReceipt `json:"actions"`
147	
148		executedAtRaw json.RawMessage
149		orderRaw      json.RawMessage
150	}
151	
152	// receiptJSONShape 只用于解码，按保存格式的字段名逐字接住每个字段的原始 JSON。
153	type receiptJSONShape struct {
154		ProposalID string          `json:"proposal_id"`
155		ExecutedAt json.RawMessage `json:"executed_at"`
156		Order      json.RawMessage `json:"order"`
157		Actions    []ActionReceipt `json:"actions"`
158	}
159	
160	// UnmarshalJSON 保留 executed_at/order 是否出现及其原始写法（缺失为 nil、null 为
161	// "null"），使“字段缺失”与“显式写出 0”在解码后仍可区分：encoding/json 直接
162	// 解进 int64 会把缺失/null/类型不符都折叠成 0，第一份凭据缺失 order 时就会被
163	// 误当成合法编号 0。判定统一交给 validateState，此处只在字段确实是 int64
164	// 整数时填充 ExecutedAt/Order。
165	func (r *Receipt) UnmarshalJSON(data []byte) error {
166		var shape receiptJSONShape
167		if err := json.Unmarshal(data, &shape); err != nil {
168			return err
169		}
170		r.ProposalID = shape.ProposalID
171		r.Actions = shape.Actions
172		r.executedAtRaw = shape.ExecutedAt
173		r.orderRaw = shape.Order
174		fillInt64(shape.ExecutedAt, &r.ExecutedAt)
175		fillInt64(shape.Order, &r.Order)
176		return nil
177	}
178	
179	// ProposalRecord 是已登记提案的对外视图。State 只可能是 passed 或 executed。
180	type ProposalRecord struct {
181		ID          string   `json:"id"`
182		State       string   `json:"state"`
183		TimelockEnd int64    `json:"timelock_end"`
184		Actions     []string `json:"actions"`
185	}
186	
187	// ---- 磁盘结构（JSON） ----
188	
189	type storedProposal struct {
190		ID          string   `json:"id"`
191		State       string   `json:"state"`
192		TimelockEnd int64    `json:"timelock_end"`
193		Actions     []string `json:"actions"`
194	}
195	
196	type storedState struct {
197		Magic           string                         `json:"magic"`
198		Version         int                            `json:"version"`
199		InitialTreasury int64                          `json:"initial_treasury"`
200		Treasury        int64                          `json:"treasury"`
201		Balances        map[string]int64               `json:"balances"`
202		Proposals       map[string]*storedProposal     `json:"proposals"`
203		Receipts        []*Receipt                     `json:"receipts"`
204		VoteProposals   map[string]*storedVoteProposal `json:"vote_proposals"`
205	}
206	
207	// Store 是绑定到单个本地状态文件的资金库句柄。
208	// 多个 goroutine 可并发使用同一个 Store；不同 Store/进程操作同一状态文件时，
209	// 通过进程内互斥锁与文件锁（flock）串行化。
210	type Store struct {
211		path   string
212		mu     sync.Mutex // 保护本句柄上的全部操作
213		lockFD *os.File   // 跨进程文件锁
214		closed bool
215	}
216	
217	// 进程内按规范路径共享的互斥锁，保证同进程内多个 Store 句柄也互相串行。
218	var (
219		pathLocksMu sync.Mutex
220		pathLocks   = map[string]*sync.Mutex{}
221	)
222	
223	// canonicalPath 将路径规范化为绝对路径，保证不同拼写（如 t.json 与 ./t.json）
224	// 命中同一把进程内锁与同一个锁文件。有意不解析符号链接：文件在初始化前后必须
225	// 解析到同一个键，硬链接/绑定挂载等更深层别名不在本地单文件场景的处理范围内。
226	func canonicalPath(path string) (string, error) {
227		return filepath.Abs(path)
228	}
229	
230	func inProcessLock(path string) *sync.Mutex {
231		pathLocksMu.Lock()
232		defer pathLocksMu.Unlock()
233		m, ok := pathLocks[path]
234		if !ok {
235			m = &sync.Mutex{}
236			pathLocks[path] = m
237		}
238		return m
239	}
240	
241	// InitTreasury 创建一个全新的状态文件并写入初始资金库余额。
242	// 只有新文件才能初始化：路径已存在（含损坏文件）一律拒绝，不会重置或覆盖。
243	// treasury 必须落在有符号 64 位整数范围内且不得为负。
244	func InitTreasury(path string, treasury int64) (*Store, error) {
245		if treasury < 0 {
246			return nil, fmt.Errorf("%w: initial treasury balance must not be negative", ErrInvalidRegistration)
247		}
248		path, err := canonicalPath(path)
249		if err != nil {
250			return nil, err
251		}
252		pathMu := inProcessLock(path)
253		pathMu.Lock()
254		defer pathMu.Unlock()
255	
256		// 先打开/创建锁文件并取跨进程锁，再创建状态文件，消除“空文件已出现、
257		// 尚未写入”期间被其它进程 Open 判为损坏的窗口。
258		lockFD, err := os.OpenFile(path+lockSuffix, os.O_RDWR|os.O_CREATE, 0o600)
259		if err != nil {
260			return nil, err
261		}
262		if err := syscall.Flock(int(lockFD.Fd()), syscall.LOCK_EX); err != nil {
263			_ = lockFD.Close()
264			return nil, err
265		}
266		// O_EXCL 保证与并发初始化竞争时只有一方成功。
267		fd, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
268		if err != nil {
269			_ = syscall.Flock(int(lockFD.Fd()), syscall.LOCK_UN)
270			_ = lockFD.Close()
271			if errors.Is(err, fs.ErrExist) {
272				return nil, fmt.Errorf("%w: %s", ErrTreasuryAlreadyInit, path)
273			}
274			return nil, err
275		}
276		_ = fd.Close()
277	
278		store := &Store{path: path, lockFD: lockFD}
279		if err := store.commitLocked(newStoredState(treasury)); err != nil {
280			_ = store.funlock()
281			_ = lockFD.Close()
282			_ = os.Remove(path)
283			return nil, err
284		}
285		// 初始化完成后立即释放跨进程锁；后续每次操作各自短持锁。
286		if err := store.funlock(); err != nil {
287			_ = lockFD.Close()
288			_ = os.Remove(path)
289			return nil, err
290		}
291		return store, nil
292	}
293	
294	// Open 打开已有的资金库状态文件。文件损坏时明确拒绝，不会重建或覆盖原文件。
295	func Open(path string) (*Store, error) {
296		path, err := canonicalPath(path)
297		if err != nil {
298			return nil, err
299		}
300		pathMu := inProcessLock(path)
301		pathMu.Lock()
302		defer pathMu.Unlock()
303		return openStoreHoldingPathLock(path)
304	}
305	
306	// openStoreHoldingPathLock 的调用方必须持有该路径的进程内互斥锁。
307	func openStoreHoldingPathLock(path string) (*Store, error) {
308		if _, err := os.Stat(path); err != nil {
309			return nil, err
310		}
311		lockFD, err := os.OpenFile(path+lockSuffix, os.O_RDWR|os.O_CREATE, 0o600)
312		if err != nil {
313			return nil, err
314		}
315		if err := syscall.Flock(int(lockFD.Fd()), syscall.LOCK_EX); err != nil {
316			_ = lockFD.Close()
317			return nil, err
318		}
319		store := &Store{path: path, lockFD: lockFD}
320		if _, err := store.loadLocked(); err != nil {
321			_ = store.funlock()
322			_ = lockFD.Close()
323			return nil, err
324		}
325		// 打开时已做严格校验；锁随即释放，每次操作再各自短持锁。
326		if err := store.funlock(); err != nil {
327			_ = lockFD.Close()
328			return nil, err
329		}
330		return store, nil
331	}
332	
333	// Path 返回状态文件路径。
334	func (s *Store) Path() string { return s.path }
335	
336	// Close 释放文件锁。关闭后其它操作返回错误。
337	func (s *Store) Close() error {
338		s.mu.Lock()
339		defer s.mu.Unlock()
340		if s.closed {
341			return nil
342		}
343		s.closed = true
344		if err := s.funlock(); err != nil {
345			_ = s.lockFD.Close()
346			return err
347		}
348		return s.lockFD.Close()
349	}
350	
351	func (s *Store) flock(how int) error {
352		if s.lockFD == nil {
353			return errors.New("treasury store is closed")
354		}
355		return syscall.Flock(int(s.lockFD.Fd()), how)
356	}
357	
358	func (s *Store) funlock() error {
359		if s.lockFD == nil {
360			return nil
361		}
362		return syscall.Flock(int(s.lockFD.Fd()), syscall.LOCK_UN)
363	}
364	
365	// begin 串行化一次读改写操作：先取进程内路径锁，再取跨进程排他文件锁。
366	// 返回的 commit 在操作结束时释放锁。
367	func (s *Store) begin() (func(), error) {
368		pathMu := inProcessLock(s.path)
369		pathMu.Lock()
370		s.mu.Lock()
371		if s.closed {
372			s.mu.Unlock()
373			pathMu.Unlock()
374			return nil, errors.New("treasury store is closed")
375		}
376		if err := s.flock(syscall.LOCK_EX); err != nil {
377			s.mu.Unlock()
378			pathMu.Unlock()
379			return nil, err
380		}
381		return func() {
382			_ = s.funlock()
383			s.mu.Unlock()
384			pathMu.Unlock()
385		}, nil
386	}
387	
388	func newStoredState(treasury int64) *storedState {
389		return &storedState{
390			Magic:           stateMagic,
391			Version:         stateVersion,
392			InitialTreasury: treasury,
393			Treasury:        treasury,
394			Balances:        map[string]int64{},
395			Proposals:       map[string]*storedProposal{},
396			Receipts:        []*Receipt{},
397			VoteProposals:   map[string]*storedVoteProposal{},
398		}
399	}
400	
401	// ---- 登记 ----
402	
403	// Register 登记一项已通过（passed）的提案，保留时间锁与动作原文。
404	// 编号必须非空；动作列表可为空（执行时会因动作为空被拒绝），动作原文不做改写。
405	// 同编号且时间锁、动作原文与首次登记完全相同的重试返回 existed=true；
406	// 内容不同则返回 ErrProposalConflict。
407	func (s *Store) Register(id string, timelockEnd int64, actions []string) (existed bool, err error) {
408		if id == "" {
409			return false, fmt.Errorf("%w: proposal id must not be empty", ErrInvalidRegistration)
410		}
411		commit, err := s.begin()
412		if err != nil {
413			return false, err
414		}
415		defer commit()
416	
417		state, err := s.loadLocked()
418		if err != nil {
419			return false, err
420		}
421		stored := copyActions(actions)
422		if existing, ok := state.Proposals[id]; ok {
423			if existing.TimelockEnd == timelockEnd && sameActions(existing.Actions, stored) {
424				return true, nil
425			}
426			return false, fmt.Errorf("%w: proposal %s", ErrProposalConflict, id)
427		}
428		// 两种来源共用编号：register 不能覆盖投票提案或绕过其投票结论。
429		if vp, ok := state.VoteProposals[id]; ok {
430			return false, fmt.Errorf("%w: proposal id %s belongs to a voting proposal (state=%s)", ErrProposalConflict, id, vp.State)
431		}
432		state.Proposals[id] = &storedProposal{
433			ID:          id,
434			State:       "passed",
435			TimelockEnd: timelockEnd,
436			Actions:     stored,
437		}
438		if err := s.commitLocked(state); err != nil {
439			return false, err
440		}
441		return false, nil
442	}
443	
444	func copyActions(actions []string) []string {
445		if actions == nil {
446			return nil
447		}
448		copied := make([]string, len(actions))
449		copy(copied, actions)
450		return copied
451	}
452	
453	// sameActions 将 nil 与空切片视为等价，其余按顺序逐字比较。
454	func sameActions(a, b []string) bool {
455		if len(a) != len(b) {
456			return false
457		}
458		for i := range a {
459			if a[i] != b[i] {
460				return false
461			}
462		}
463		return true
464	}
465	
466	// ---- 执行 ----
467	
468	// executionTarget 是 register 与投票两种来源提案在执行路径上的统一视图。
469	type executionTarget struct {
470		state        string
471		timelockEnd  int64
472		actions      []string
473		markExecuted func()
474	}
475	
476	// resolveExecutable 在两种提案表中按编号定位执行目标；不存在返回 nil。
477	func resolveExecutable(state *storedState, id string) *executionTarget {
478		if p, ok := state.Proposals[id]; ok {
479			return &executionTarget{
480				state:        p.State,
481				timelockEnd:  p.TimelockEnd,
482				actions:      p.Actions,
483				markExecuted: func() { p.State = "executed" },
484			}
485		}
486		if vp, ok := state.VoteProposals[id]; ok {
487			return &executionTarget{
488				state:        vp.State,
489				timelockEnd:  vp.TimelockEnd,
490				actions:      vp.Actions,
491				markExecuted: func() { vp.State = "executed" },
492			}
493		}
494		return nil
495	}
496	
497	// proposalOwners 将两个来源的提案编号映射到状态、时间锁与动作，供凭据重放交叉校验。
498	func proposalOwnerState(state *storedState, id string) (string, int64, []string, bool) {
499		if p, ok := state.Proposals[id]; ok {
500			return p.State, p.TimelockEnd, p.Actions, true
501		}
502		if vp, ok := state.VoteProposals[id]; ok {
503			return vp.State, vp.TimelockEnd, vp.Actions, true
504		}
505		return "", 0, nil, false
506	}
507	
508	// Execute 按编号执行一项提案。调用方通过 now 提供当前时间。
509	// 只有 passed 状态、now 已达到时间锁且动作非空的提案可以首次执行；
510	// 成功后状态变为 executed 并返回凭据。资格不符、动作格式错误、余额不足、
511	// 金额计算溢出都返回明确原因，整项提案不产生部分转账，也不消耗执行机会。
512	// 已完成提案再次执行（即使 now 不同）直接返回首次成功凭据。
513	func (s *Store) Execute(id string, now int64) (*Receipt, error) {
514		commit, err := s.begin()
515		if err != nil {
516			return nil, err
517		}
518		defer commit()
519	
520		state, err := s.loadLocked()
521		if err != nil {
522			return nil, err
523		}
524		target := resolveExecutable(state, id)
525		if target == nil {
526			return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
527		}
528		if target.state == "executed" {
529			if rcpt := findReceipt(state.Receipts, id); rcpt != nil {
530				return cloneReceipt(rcpt), nil
531			}
532			return nil, fmt.Errorf("%w: executed proposal %s has no receipt", ErrStateCorrupt, id)
533		}
534		if target.state != "passed" {
535			return nil, execReject(fmt.Sprintf("proposal %s is not passed (state=%s)", id, target.state))
536		}
537		if now < target.timelockEnd {
538			return nil, execReject(fmt.Sprintf("timelock not reached for %s: now=%d timelock_end=%d", id, now, target.timelockEnd))
539		}
540		if len(target.actions) == 0 {
541			return nil, execReject(fmt.Sprintf("proposal %s has no actions", id))
542		}
543	
544		// 第一阶段：在副本上按统一转账规则（planTransfers）校验并预演全部
545		// 动作。任何一步失败都直接返回，副本之外的状态不落盘。
546		steps, simTreasury, simBalances, perr := planTransfers(target.actions, state.Treasury, state.Balances)
547		if perr != nil {
548			return nil, perr
549		}
550	
551		// 第二阶段：全部预演成功后构造凭据并一次性原子提交。
552		receipt := &Receipt{
553			ProposalID: id,
554			ExecutedAt: now,
555			Order:      int64(len(state.Receipts)),
556			Actions:    make([]ActionReceipt, 0, len(steps)),
557		}
558		// 同步填上字段原始片段，使“提交前校验”与“打开重放校验”走同一份
559		// executed_at/order 判定时不会把本进程新建的凭据误判为字段缺失。
560		receipt.executedAtRaw, _ = json.Marshal(now)
561		receipt.orderRaw, _ = json.Marshal(receipt.Order)
562		for i, st := range steps {
563			receipt.Actions = append(receipt.Actions, st.actionReceipt(i, target.actions[i]))
564		}
565		state.Treasury = simTreasury
566		state.Balances = simBalances
567		target.markExecuted()
568		state.Receipts = append(state.Receipts, receipt)
569	
570		if err := s.commitLocked(state); err != nil {
571			return nil, err
572		}
573		return cloneReceipt(receipt), nil
574	}
575	
576	func findReceipt(receipts []*Receipt, id string) *Receipt {
577		for _, r := range receipts {
578			if r.ProposalID == id {
579				return r
580			}
581		}
582		return nil
583	}
584	
585	func cloneReceipt(r *Receipt) *Receipt {
586		if r == nil {
587			return nil
588		}
589		copied := *r
590		if r.Actions != nil {
591			copied.Actions = make([]ActionReceipt, len(r.Actions))
592			copy(copied.Actions, r.Actions)
593		}
594		return &copied
595	}
