678	func proposalRecords(state *storedState) []ProposalRecord {
679		out := make([]ProposalRecord, 0, len(state.Proposals))
680		for _, p := range state.Proposals {
681			out = append(out, toProposalRecord(p))
682		}
683		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
684		return out
685	}
