1046			err := validateRawFields([]rawField{
1047				{name: "before", kind: scalarInteger, raw: side.update.beforeRaw},
1048				{name: "after", kind: scalarInteger, raw: side.update.afterRaw},
1049			}, func(field, problem string) error {
1050				return fmt.Errorf("receipt for proposal %q action %d %s field %q %s",
1051					id, index, side.name, field, problem)
1052			})
1053			if err != nil {
1054				return err
1055			}
1056		}
1057		return nil
1058	}
