1140		tallyFields := storedStateSchema.fields["vote_proposals"].elem.fields["tally"].fields
1141		for _, name := range []string{"for_weight", "against_weight"} {
1142			tallyFields[name].kind = kindAny
1143		}
1144		// 凭据的 executed_at 同理：缺失/空值/类型不符/早于时间锁的判定需要带上
1145		// 提案编号与凭据位置，统一由 validateReceiptExecutedAt 报错，结构扫描在此
1146		// 叶子位置保持宽松。
1147		receiptFields := storedStateSchema.fields["receipts"].elem.fields
1148		receiptFields["executed_at"].kind = kindAny
1149		// 凭据的 order 同理：缺失/空值/类型不符/位置不符的判定需要带上提案编号与
1150		// 凭据位置，统一由 validateReceiptOrder 报错，结构扫描在此叶子位置保持宽松。
1151		receiptFields["order"].kind = kindAny
1152		// 凭据逐笔留痕的 index 同理：缺失/空值/类型不符/位置不符的判定需要带上
1153		// 提案编号与动作下标，统一由 validateReceiptActionIndex 报错，结构扫描在
1154		// 此叶子位置保持宽松。
1155		receiptFields["actions"].elem.fields["index"].kind = kindAny
1156		// 凭据逐笔留痕的四个余额字段（treasury/recipient 的 before/after）同理：
1157		// 缺失/空值/类型不符的判定需要带上提案编号、动作下标与所在侧，统一由
1158		// validateReceiptActionBalances 报错，结构扫描在这些叶子位置保持宽松。
