1167	// scanFrame 是结构扫描的栈帧。
1168	type scanFrame struct {
1169		node    *schemaNode
1170		isArray bool
1171		opaque  bool // 形状不符或叶子位置的容器：只配对括号，类型错误交给解码器报告
1172		seen    map[string]bool
1173		atValue bool // 对象帧：下一个待消费 token 是值而非键
1174		index   int  // 数组帧：下一个元素下标
1175		path    string
1176	}
1177	
1178	func peekFrame(stack []*scanFrame) *scanFrame {
1179		if len(stack) == 0 {
1180			return nil
1181		}
1182		return stack[len(stack)-1]
1183	}
1184	
1185	// checkStateStructure 在解码前逐 token 扫描状态文件：
1186	//   - 同一对象内键（按 JSON 解读后的字符串，转义拼写与普通拼写视为同一键）不得重复；
1187	//   - 固定字段对象的键必须与保存格式的字段名逐字一致：大小写变体（如 Treasury、
1188	//     Support）与未知字段一样拒绝，避免解码器的大小写折叠把两份值并入同一字段；
1189	//   - balances/proposals/vote_proposals 等业务编号表的键是自由文本，
1190	//     Audit 与 audit、GIP-1 与 gip-1 是不同账户/编号，不做字段名检查。
1191	//
1192	// 报错带有出问题的字段与所在记录的路径（如 vote_proposals["GIP-1"].ballots[0]），
1193	// 便于定位。字段顺序、缩进与合法转义不影响判定。
1194	func checkStateStructure(raw []byte) error {
1195		dec := json.NewDecoder(bytes.NewReader(raw))
1196		// UseNumber：数字 token 保留词面写法，整数叶子可据此精确判定 int64 范围，
1197		// 不被 float64 在 2^63 附近的舍入混淆（MaxInt64 与 MaxInt64+1 会折成同一浮点）。
1198		dec.UseNumber()
1199		var stack []*scanFrame
1200		// 对象帧读到键时，把该键对应值的形状与路径暂存于此，供紧随其后的值使用。
1201		pendingNode := storedStateSchema
1202		pendingPath := "state"
1203	
1204		// 一个值消费完毕：推进父帧的键/值位置或数组下标。
1205		finishValue := func() {
1206			top := peekFrame(stack)
1207			if top == nil || top.opaque {
1208				return
1209			}
1210			if top.isArray {
1211				top.index++
1212			} else {
1213				top.atValue = false
1214			}
1215		}
1216	
1217		for {
1218			tok, err := dec.Token()
1219			if err == io.EOF {
1220				if len(stack) != 0 {
1221					return errors.New("unterminated object or array")
1222				}
1223				return nil
1224			}
1225			if err != nil {
1226				return err
1227			}
1228	
1229			if top := peekFrame(stack); top != nil && top.opaque {
1230				// 不透明容器内不做字段检查，只配对括号。
1231				if d, ok := tok.(json.Delim); ok {
1232					if d == '{' || d == '[' {
1233						stack = append(stack, &scanFrame{opaque: true})
1234					} else {
1235						stack = stack[:len(stack)-1]
1236						finishValue()
1237					}
1238				}
1239				continue
1240			}
1241	
1242			if top := peekFrame(stack); top != nil && !top.isArray && !top.atValue {
1243				// 对象帧的键位置：闭括号或下一个键。
1244				if d, ok := tok.(json.Delim); ok {
1245					if d != '}' {
1246						return fmt.Errorf("unexpected %q inside object at %s", string(d), top.path)
1247					}
1248					stack = stack[:len(stack)-1]
1249					finishValue()
1250					continue
1251				}
1252				key, ok := tok.(string)
1253				if !ok {
1254					return errors.New("object key must be a string")
1255				}
1256				if top.seen[key] {
1257					return fmt.Errorf("duplicate key %q at %s", key, top.path)
1258				}
1259				top.seen[key] = true
1260				top.atValue = true
1261				switch top.node.kind {
1262				case kindObject:
1263					child, known := top.node.fields[key]
1264					if !known {
1265						return fmt.Errorf("unknown field %q at %s", key, top.path)
1266					}
1267					pendingNode = child
1268					pendingPath = top.path + "." + key
1269				case kindMap:
1270					// 业务编号是自由文本，大小写变体属于不同编号，不得拒绝或合并。
1271					pendingNode = top.node.elem
1272					pendingPath = top.path + "[" + strconv.Quote(key) + "]"
1273				}
1274				continue
1275			}
1276	
1277			// 值位置：对象键之后的值或数组元素。
1278			node := pendingNode
1279			path := pendingPath
1280			if top := peekFrame(stack); top != nil && top.isArray {
1281				node = top.node.elem
1282				path = top.path + "[" + strconv.Itoa(top.index) + "]"
1283			}
1284			if d, ok := tok.(json.Delim); ok {
1285				switch d {
1286				case '{', '[':
1287					frame := &scanFrame{isArray: d == '[', path: path}
1288					shapeOK := (d == '{' && (node.kind == kindObject || node.kind == kindMap)) ||
1289						(d == '[' && node.kind == kindArray)
1290					if !shapeOK {
1291						// 叶子位置出现容器或形状不符：跳过内容，类型错误由解码器报告。
1292						frame.opaque = true
1293					} else {
1294						frame.node = node
1295						if d == '{' {
1296							frame.seen = map[string]bool{}
1297						}
1298					}
1299					stack = append(stack, frame)
1300				default: // '}' 或 ']'：数组结束（对象的闭括号已在键位置处理）
1301					if len(stack) == 0 {
1302						return errors.New("unexpected closing delimiter")
1303					}
1304					stack = stack[:len(stack)-1]
1305					finishValue()
1306				}
1307				continue
1308			}
1309			// 标量值（含 null）：严格叶子必须与字段声明的 JSON 类型逐字一致，
1310			// null 不允许用来顶替字符串/布尔/整数。
1311			if err := checkLeafScalar(node, path, tok); err != nil {
1312				return err
1313			}
1314			finishValue()
1315		}
1316	}
1317	
1318	// leafKindName 是严格叶子类型在错误信息中的人类可读名称。
1319	func leafKindName(k schemaKind) string {
1320		switch k {
1321		case kindString:
1322			return "string"
1323		case kindBoolean:
1324			return "boolean"
1325		case kindInteger:
1326			return "integer"
1327		default:
1328			return "value"
1329		}
1330	}
1331	
1332	// tokenKindName 归类一个标量 token 实际写出的 JSON 类型。
1333	func tokenKindName(tok json.Token) string {
1334		switch v := tok.(type) {
1335		case nil:
1336			return "null"
1337		case string:
1338			return "string"
1339		case bool:
1340			return "boolean"
1341		case json.Number:
1342			if _, err := strconv.ParseInt(string(v), 10, 64); err == nil {
1343				return "integer"
1344			}
1345			return "number"
1346		default:
1347			return "value"
1348		}
1349	}
1350	
1351	// checkLeafScalar 校验严格标量叶子：字符串/布尔/int64 整数位置出现 null 或
1352	// 其它 JSON 类型即判结构损坏。非整数（小数、指数）或超出 int64 的整数同样拒绝。
1353	func checkLeafScalar(node *schemaNode, path string, tok json.Token) error {
1354		switch node.kind {
1355		case kindString, kindBoolean, kindInteger:
1356		default:
1357			return nil
1358		}
1359		if node.kind == kindInteger {
1360			if n, ok := tok.(json.Number); ok {
1361				if _, err := strconv.ParseInt(string(n), 10, 64); err != nil {
1362					return fmt.Errorf("field at %s must be an int64 integer, got %s", path, string(n))
1363				}
1364				return nil
1365			}
1366		}
1367		want := leafKindName(node.kind)
1368		if got := tokenKindName(tok); got != want {
1369			return fmt.Errorf("field at %s must be %s, got %s", path, want, got)
1370		}
1371		return nil
1372	}
1373

