// 收款账户完全对应。把 legal:50 换成 ghost:0（账户数量不变）、额外加入无凭据
// 支持的账户、或已记录余额与凭据累计不符，都判整份状态损坏，错误指出涉及的
// 账户名称；合法累计余额与空余额表不受影响。
func TestBalanceTableMustMatchReceipts(t *testing.T) {
	dir := t.TempDir()
