	mutateBalances := func(fn func(balances map[string]any)) []byte {
		var root map[string]any
		if err := json.Unmarshal(good, &root); err != nil {
			t.Fatal(err)
		}
		fn(root["balances"].(map[string]any))
		raw, err := json.MarshalIndent(root, "", "  ")
		if err != nil {
			t.Fatal(err)
		}
		return append(raw, '\n')
	}

